CREATE TABLE IF NOT EXISTS "traffic_event_outbox" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "event_id" UUID NOT NULL,
    "server_id" BIGINT NOT NULL,
    "user_id" BIGINT NOT NULL,
    "user_subscribe_id" BIGINT NOT NULL,
    "download" BIGINT NOT NULL DEFAULT 0,
    "upload" BIGINT NOT NULL DEFAULT 0,
    "event_time" TIMESTAMPTZ NOT NULL,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id"),
    CONSTRAINT "idx_traffic_event_outbox_event_id" UNIQUE ("event_id")
);

CREATE INDEX IF NOT EXISTS "idx_traffic_event_outbox_pending"
    ON "traffic_event_outbox" ("id", "created_at");

INSERT INTO "traffic_event_outbox" (
    "event_id", "server_id", "user_id", "user_subscribe_id",
    "download", "upload", "event_time", "created_at"
)
SELECT
    md5('alpha-traffic-log:' || "id"::text)::uuid,
    "server_id", "user_id", "subscribe_id", "download", "upload", "timestamp", CURRENT_TIMESTAMP
FROM "traffic_log"
ON CONFLICT ("event_id") DO NOTHING;
